import{bQ as t,aL as a,u as o,G as n}from"./chunks/framework.igrrHzX3.js";const r="/knowledge/images/architecture-components.svg",s="/knowledge/images/workflow.svg",u=JSON.parse('{"title":"Understanding knowledge","description":"","frontmatter":{},"headers":[],"relativePath":"guides/understanding.md","filePath":"guides/understanding.md"}'),d={name:"guides/understanding.md"};function i(h,e,l,c,m,g){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="understanding-knowledge" tabindex="-1">Understanding knowledge <a class="header-anchor" href="#understanding-knowledge" aria-label="Permalink to &quot;Understanding knowledge&quot;">​</a></h1><p>knowledge is a <a href="/knowledge/about/introduction.html">RAG</a> <strong>specialised in the Kalisio ecosystem</strong>. It indexes the Kalisio repositories (source code, documentation, helm charts etc.) and answers questions about them, with the passages it answered from.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><p><img src="'+r+'" alt="Components"></p><table tabindex="0"><thead><tr><th>Component</th><th>Role</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Ingestion job</strong></td><td>Builds and maintains the index: clones the repositories, cuts every supported file into chunks, embeds them, writes them to Qdrant, only what changed since the last run</td><td><a href="/knowledge/guides/components/ingestion-job.html">Ingestion job</a></td></tr><tr><td><strong>API</strong></td><td>Reads the index: embeds a question, searches Qdrant, returns the passages or an answer written by an LLM</td><td><a href="/knowledge/guides/components/api.html">API</a></td></tr><tr><td><strong>Qdrant</strong></td><td>Stores one vector + payload per chunk, finds the nearest ones to a query vector</td><td><a href="/knowledge/guides/components/qdrant.html">Qdrant</a></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The job and the API share <strong>no code</strong>: they are two images, deployed apart, and their only contract is the shape of what they store in and read from Qdrant, plus one rule: <strong>both must use the same embedding model</strong>, or a question vector and a chunk vector are not comparable.</p></div><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p>Every passage knowledge returns has made the same journey:</p><p><img src="'+s+'" alt="From a file to an answer"></p><h3 id="_1-clone-scan" tabindex="-1">1. Clone &amp; scan <a class="header-anchor" href="#_1-clone-scan" aria-label="Permalink to &quot;1. Clone &amp; scan&quot;">​</a></h3><p>The job fills a workspace with the repositories of a <a href="https://github.com/kalisio/kli" target="_blank" rel="noreferrer">kli</a> workspace by running <code>k-clone</code> from <a href="https://github.com/kalisio/development" target="_blank" rel="noreferrer"><code>kalisio/development</code></a>. It then lists the files and keeps those with a supported extension. See <a href="/knowledge/guides/components/ingestion-job.html#step-4-scanning-the-workspace">Ingestion job › Scanning</a>.</p><h3 id="_2-parse-chunk" tabindex="-1">2. Parse &amp; chunk <a class="header-anchor" href="#_2-parse-chunk" aria-label="Permalink to &quot;2. Parse &amp; chunk&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Format</th><th>Extensions</th><th>Cut along</th><th>Guide</th></tr></thead><tbody><tr><td>Markdown</td><td><code>.md</code></td><td>headings, sections merged up to 500 characters, code blocks never split</td><td><a href="/knowledge/guides/file-formats/markdown.html">Markdown</a></td></tr><tr><td>JavaScript</td><td><code>.js</code> <code>.mjs</code> <code>.cjs</code></td><td>JavaScript syntax boundaries, each chunk tagged with its top-level symbol</td><td><a href="/knowledge/guides/file-formats/javascript.html">JavaScript</a></td></tr><tr><td>Vue</td><td><code>.vue</code></td><td>the <code>&lt;template&gt;</code>, <code>&lt;script&gt;</code>, <code>&lt;style&gt;</code> blocks, each split with the right splitter</td><td><a href="/knowledge/guides/file-formats/vue.html">Vue</a></td></tr><tr><td>JSON</td><td><code>.json</code></td><td>its role: a schema per property, a translation file per section; other JSON skipped</td><td><a href="/knowledge/guides/file-formats/json.html">JSON</a></td></tr><tr><td>YAML</td><td><code>.yaml</code> <code>.yml</code> <code>.gotmpl</code></td><td>top-level keys (then second-level ones for large keys), Kubernetes documents by kind</td><td><a href="/knowledge/guides/file-formats/yaml.html">YAML</a></td></tr><tr><td>Shell</td><td><code>.sh</code></td><td>functions, with their comment header</td><td><a href="/knowledge/guides/file-formats/shell.html">Shell</a></td></tr></tbody></table><h3 id="_3-embed" tabindex="-1">3. Embed <a class="header-anchor" href="#_3-embed" aria-label="Permalink to &quot;3. Embed&quot;">​</a></h3><p>Each chunk is turned into a <strong>1 024-dimensional vector</strong> by <a href="https://huggingface.co/Qwen/Qwen3-Embedding-0.6B" target="_blank" rel="noreferrer">Qwen3-Embedding-0.6B</a>, an open, multilingual, code-aware model. See <a href="/knowledge/guides/file-formats/#the-embedding-model">File formats › The embedding model</a>.</p><h3 id="_4-store" tabindex="-1">4. Store <a class="header-anchor" href="#_4-store" aria-label="Permalink to &quot;4. Store&quot;">​</a></h3><p>Each chunk becomes one <strong>Qdrant point</strong>: the vector, plus a payload holding the text, the repository, the path, the line range, the breadcrumb and the digests that drive change detection. See <a href="/knowledge/guides/components/qdrant.html">Qdrant</a>.</p><h3 id="_5-search" tabindex="-1">5. Search <a class="header-anchor" href="#_5-search" aria-label="Permalink to &quot;5. Search&quot;">​</a></h3><p>The API embeds the question with the same model and asks Qdrant for the nearest chunks. Because the model is multilingual, a French question already reaches English passages; to close the remaining gap, the API can also translate the question with small <a href="https://marian-nmt.github.io/" target="_blank" rel="noreferrer">Marian</a> models (French → English and English → French), search every phrasing, and keep each passage&#39;s best score. See <a href="/knowledge/guides/components/api.html#multilingual-retrieval">API › Multilingual retrieval</a>.</p><h3 id="_6-generate" tabindex="-1">6. Generate <a class="header-anchor" href="#_6-generate" aria-label="Permalink to &quot;6. Generate&quot;">​</a></h3><p><code>/search</code> stops there and returns the passages. <code>/ask</code> goes on: it packs the passages into a context (up to 14 000 characters), adds an instruction and the question, and sends them to an LLM through any <a href="https://platform.openai.com/docs/api-reference/chat" target="_blank" rel="noreferrer">OpenAI-compatible</a> endpoint, Anthropic, OpenAI, Mistral, a local Ollama... The answer comes back in the language of the question, with the passages it was written from. See <a href="/knowledge/guides/components/api.html#post-ask">API › POST /ask</a>.</p>',21)])])}const k=t(d,[["render",i]]);export{u as __pageData,k as default};
